<?php
namespace App\Entity;
use Doctrine\Common\Collections\ArrayCollection; use Doctrine\Common\Collections\Collection; use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity] class Simulation { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne(inversedBy:'simulations')] #[ORM\JoinColumn(nullable:false)] private ?Saison $saison=null; #[ORM\Column(length:150)] private string $nom=''; #[ORM\Column(type:'datetime')] private \DateTimeInterface $dateCreation; #[ORM\Column(length:30)] private string $statut='preparee'; #[ORM\Column(nullable:true)] private ?int $seed=null; #[ORM\Column(type:'datetime',nullable:true)] private ?\DateTimeInterface $dateDebut=null; #[ORM\Column(type:'datetime',nullable:true)] private ?\DateTimeInterface $dateFin=null; #[ORM\OneToMany(mappedBy:'simulation',targetEntity:SimulationCourse::class)] private Collection $courses; public function __construct(){$this->dateCreation=new \DateTimeImmutable();$this->courses=new ArrayCollection();} public function getId():?int{return $this->id;} public function getSaison():?Saison{return $this->saison;} public function setSaison(?Saison $v):self{$this->saison=$v;return $this;} public function getNom():string{return $this->nom;} public function setNom(string $v):self{$this->nom=$v;return $this;} public function getDateCreation():\DateTimeInterface{return $this->dateCreation;} public function getStatut():string{return $this->statut;} public function setStatut(string $v):self{$this->statut=$v;return $this;} public function getSeed():?int{return $this->seed;} public function setSeed(?int $v):self{$this->seed=$v;return $this;} public function getDateDebut():?\DateTimeInterface{return $this->dateDebut;} public function setDateDebut(?\DateTimeInterface $v):self{$this->dateDebut=$v;return $this;} public function getDateFin():?\DateTimeInterface{return $this->dateFin;} public function setDateFin(?\DateTimeInterface $v):self{$this->dateFin=$v;return $this;} public function getCourses():Collection{return $this->courses;} }
